'use strict';

// Shared costing records are loaded read-only. Every write has an explicit user action.
window.LumiCost = (() => {
  let ctx, active=false, epoch=0, busy=false, error='', projectId='', tab='overview';
  let workspace=null, knowledge={processes:[]}, estimates=[], selected='', quoteEditor=null, importState=null;
  let routeEditor=null, compareResult=null, actualEditor=null, issueEditor=null, revisionDetail=null;
  const drafts=new Map(), selectedByProject=new Map();
  const taxLabels={unknown:'税口径待确认',included:'含税',excluded:'不含税'};
  const shipLabels={unknown:'运费待确认',included:'已含运费',excluded:'未含运费'};
  const categoryLabels={electronic:'电子件',structure:'结构件 / 金属材料',plastic:'塑料粒子',packaging:'包装',external_service:'委外服务',tooling:'独立模具'};
  const bucketLabels={material:'生产耗用',procurement:'采购支出',manufacturing:'内部加工',mva:'内部加工 MVA',outsourced:'委外服务',tooling:'独立模具',packaging:'包装',logistics:'物流',consumption:'生产耗用',factory_management:'工厂管理费用'};
  const list=value=>Array.isArray(value)?value:[];
  const clone=value=>JSON.parse(JSON.stringify(value));
  const esc=value=>ctx.esc(value ?? '');
  const num=(value,digits=3)=>typeof value==='number'&&Number.isFinite(value)?(ctx.num?.(value,digits) ?? value.toFixed(digits)):'—';
  const today=()=>new Date(Date.now()+8*3600000).toISOString().slice(0,10);
  const finite=value=>typeof value==='number'&&Number.isFinite(value);
  const money=(value,currency='CNY')=>finite(value)?`${num(value,4)} ${esc(currency)}`:'待确认';
  const $=selector=>document.querySelector(selector);
  const option=(value,label,current)=>`<option value="${esc(value)}" ${String(current)===String(value)?'selected':''}>${esc(label)}</option>`;
  const options=(rows,current)=>rows.map(row=>option(row[0],row[1],current)).join('');
  const button=(action,label,extra='',primary=false)=>`<button type="button" class="button button-small${primary?' button-primary':''}" data-cost-action="${action}" ${extra} ${busy?'disabled':''}>${label}</button>`;
  const badge=(label,tone='')=>`<span class="cw-badge ${tone}">${esc(label)}</span>`;
  const note=(message,warning=false)=>`<div class="cw-note${warning?' warning':''}" role="status">${esc(message)}</div>`;
  const heading=(eyebrow,title,summary,actions='')=>`<div class="cw-heading"><div><p class="eyebrow">${esc(eyebrow)}</p><h2>${esc(title)}</h2><p>${esc(summary)}</p></div><div class="cw-actions">${actions}</div></div>`;
  const field=(data,name,label,{type='text',hint='',required=false,min=0,step='any',maxLength=2000}={})=>`<label class="field">${esc(label)}<input name="${esc(name)}" type="${type}" value="${esc(data?.[name] ?? '')}" ${required?'required':''} ${type==='number'?`min="${min}" step="${step}"`:`maxlength="${maxLength}"`}>${hint?`<small>${esc(hint)}</small>`:''}</label>`;
  const select=(name,label,rows,value,hint='')=>`<label class="field">${esc(label)}<select name="${esc(name)}">${options(rows,value)}</select>${hint?`<small>${esc(hint)}</small>`:''}</label>`;
  const textarea=(data,name,label,hint='')=>`<label class="field cw-wide">${esc(label)}<textarea name="${esc(name)}" rows="2" maxlength="5000">${esc(data?.[name] ?? '')}</textarea>${hint?`<small>${esc(hint)}</small>`:''}</label>`;
  const project=()=>workspace?.project || ctx.current?.();
  const revisions=()=>list(workspace?.revisions);
  const quotes=()=>list(workspace?.quotes);
  const routes=()=>list(workspace?.routes);
  const scenarios=()=>list(workspace?.scenarios);
  const scenario=()=>scenarios().find(row=>row.id===selected);
  const frozen=()=>scenario()?.status==='frozen' || Boolean(scenario()?.frozen_at);
  const evidenceUrl=value=>typeof value==='string'&&(/^\/api\/(?:costing\/evidence\/[a-f0-9]{64}\.(?:xlsx|csv|tsv)|supplier-quotes\/[a-zA-Z0-9_-]+\/file)$/.test(value)||/^https:\/\/[^\s<>"']+$/.test(value))?value:null;
  const base=()=>`/api/projects/${encodeURIComponent(projectId)}`;
  const scenarioPath=id=>base()+'/cost-scenarios/'+encodeURIComponent(id);
  const key=()=>projectId+'::'+(selected||'new');
  function initialDraft(row) {
    const input=row?.inputs || row?.input || row || {};
    return {name:input.name || row?.name || '',revision_id:input.revision_id || '',quantity_good:input.quantity_good ?? '',as_of:input.as_of || today(),lines:clone(list(input.lines)),route_id:input.route_id || '',logistics:clone(input.logistics || {mode:'none'}),management_fee:clone(input.management_fee || {status:'inherit',per_unit:'',currency:'CNY',tax_basis:'unknown',reason:''}),coverage:clone(input.coverage || Object.fromEntries(['bom','manufacturing','packaging','logistics'].map(k=>[k,{status:'unknown',reason:''}]))),...('expected_updated_at' in input?{expected_updated_at:input.expected_updated_at}:{} )};
  }
  function draft(){if(!drafts.has(key()))drafts.set(key(),initialDraft(scenario()));return drafts.get(key());}
  function assignForm(form,target){for(const el of form?.elements || [])if(el.name && Object.hasOwn(target,el.name)&&!el.closest?.('[data-cost-line],[data-cost-tier],[data-cost-operation]'))target[el.name]=el.type==='checkbox'?el.checked:el.value;}
  function remember(){
    const form=$('#cw-scenario-form');if(form?.dataset?.context===key()){
      assignForm(form,draft());
      for(const row of form.querySelectorAll?.('[data-cost-line]') || []){const line=draft().lines.find(item=>item.id===row.dataset.costLine);if(line)for(const el of row.querySelectorAll?.('[name]') || [])if(el.name)line[el.name]=el.value;}
    }
    const logisticsFields=new Set(['mode','currency','tax_basis','shipping_basis','source','origin','port','valid_until','notes','confirmed','amount','distance_km','loaded_lamps','fuel_l_per_100km','diesel_per_litre','tolls','other']);
    for(const el of $('#cw-logistics-form')?.elements || [])if(el.name&&logisticsFields.has(el.name))draft().logistics[el.name]=el.type==='checkbox'?el.checked:el.value;
    for(const row of $('#cw-coverage-form')?.querySelectorAll?.('[data-cost-coverage]') || []){const target=draft().coverage[row.dataset.costCoverage];if(target)for(const el of row.querySelectorAll?.('[name]') || [])target[el.name]=el.value;}
    assignForm($('#cw-management-form'),draft().management_fee);
    if(quoteEditor){assignForm($('#cw-quote-form'),quoteEditor);captureTiers();}
    if(routeEditor)captureRoute();
    if(actualEditor)assignForm($('#cw-actual-form'),actualEditor);
    if(issueEditor)assignForm($('#cw-issue-form'),issueEditor);
  }
  function init(context){ctx=context;}
  async function load(pid=ctx.current?.()?.id || '',view='overview') {
    remember();const token=++epoch, next=String(pid||'');
    if(projectId!==next){projectId=next;workspace=null;selected=selectedByProject.get(next)||'';quoteEditor=null;routeEditor=null;actualEditor=null;issueEditor=null;revisionDetail=null;compareResult=null;importState=null;busy=false;}
    tab=['overview','procurement','route','compare'].includes(view)?view:'overview';busy=false;error='';
    if(!next)return null;
    const values=await Promise.allSettled([ctx.api(base()+'/cost-workspace'),ctx.api('/api/manufacturing/knowledge'),ctx.api(base()+'/manufacturing')]);
    if(token!==epoch || next!==projectId)return null;
    if(values[0].status==='fulfilled'){
      workspace=values[0].value;const rows=scenarios();if(selected&&!rows.some(row=>row.id===selected))selected='';if(!selected&&rows.length)selected=rows[0].id;
      selectedByProject.set(projectId,selected);if(selected){try{const full=await ctx.api(base()+'/cost-scenarios/'+encodeURIComponent(selected));if(token!==epoch||next!==projectId)return null;workspace.scenarios=scenarios().map(row=>row.id===full.id?full:row);}catch(detailError){error=detailError.message || '所选方案明细未读取';}}draft();
    }else error=values[0].reason?.message || '成本资料未读取；输入仍保留';
    if(values[1].status==='fulfilled')knowledge=values[1].value || {processes:[]};
    if(values[2].status==='fulfilled')estimates=list(values[2].value?.estimates);
    return workspace;
  }
  function paint(){const host=$('#content');if(!active || !host || host.dataset?.page&&host.dataset.page!=='cost')return;const content=view();host.innerHTML=typeof ctx.shell==='function'?ctx.shell(content):content;afterRender();if(typeof hydrateIcons==='function')hydrateIcons(host);}
  function afterRender(){active=true;updateFreezeControl();}
  function stop(){remember();active=false;++epoch;busy=false;}
  function emptyProject(){return `<section class="panel cw-empty">${ctx.icon?.('FolderKanban') || ''}<h2>选择一个照明项目，开始核价</h2><p>成本版本与产品定义、报价和工艺路线关联。</p><a class="button button-primary" href="#projects">打开项目数据库</a></section>`;}
  function toolbar(){
    const d=draft(), s=scenario();
    return `<div class="cw-toolbar"><label class="cw-selector"><span>成本方案</span><select data-cost-select="scenario">${option('','新成本草稿',selected)}${scenarios().map(row=>option(row.id,`${row.name || '未命名'} · ${row.status==='frozen'?'已冻结':'草稿'}`,selected)).join('')}</select></label><div class="cw-context">${badge(s?.status==='frozen'?'冻结快照':s?'已保存草稿':'尚未保存',s?.status==='frozen'?'blue':'')}<span>${esc(d.quantity_good || '—')} 交付良品（只 / 套） · ${esc(d.as_of || '核价日期待填')}</span></div><div class="cw-actions">${button('new','新建成本方案')}${button('reload','重新读取')}</div></div>`;
  }
  function revisionsView(){return `<details class="cw-version-panel"><summary>产品版本与来源依据 <span>${revisions().length} 个版本</span></summary><p>保存当前产品定义、BOM 与工程资料的版本。成本冻结保留所用输入；不代表工程准许量产。</p><form id="cw-revision-form" class="cw-inline-form"><label class="field">版本名称<input name="label" maxlength="120" placeholder="例如：A60 / 工程版 B" required></label><button type="submit" class="button button-small" ${busy?'disabled':''}>保存当前产品版本</button></form>${revisions().length?`<div class="cw-version-list">${revisions().map(row=>`<div><strong>${esc(row.label || row.name || row.id)}</strong><span>${esc(row.created_at || '')}</span>${badge(`${row.file_count ?? list(row.files || row.attachments || row.sources).length} 份关联资料`)}${row.id?`<code>${esc(row.id)}</code>`:''}${button('revision-open','查看定义与原件',`data-id="${esc(row.id)}"`)}</div>`).join('')}</div>`:'<p class="cw-muted">尚无产品版本。先核对项目定义，再保存真实工程版本。</p>'}</details>`;}
  function revisionDetailView(){
    const r=revisionDetail;if(!r)return '';const p=r.snapshot || {}, spec=p.spec || {};
    const titles={power_w:'当前研发瓦数 W',power_options_w:'立项瓦数 W',luminous_flux_lm:'目标光通量 lm',cct_k:'目标色温 K',scrap_rate:'研发测算损耗率',lumens:'目标光通量 lm',cct:'目标色温 K',cri:'显色指数',beam_angle:'光束角 °',voltage:'电压',quantity:'订单量',length_mm:'长度 mm',diameter_mm:'直径 mm'};
    return `<section class="panel cw-revision-detail">${heading('产品版本快照',r.label || r.id,r.notice || '当时的产品定义与资料保留于此版本。',button('revision-close','关闭'))}<div class="cw-revision-facts"><div><small>项目 / 型号</small><strong>${esc(p.name || p.model || '待定义')}</strong></div><div><small>目标国家 / 产品类别</small><strong>${esc(p.country || '国家未知')} · ${esc(p.category || '类别未知')}</strong></div>${Object.entries(spec).map(([k,v])=>`<div><small>${esc(titles[k] || k)}</small><strong>${esc(typeof v==='object'?JSON.stringify(v):v)}</strong></div>`).join('')}</div>${list(r.warnings).length?note(list(r.warnings).join('；'),true):''}<div class="cw-section-heading"><h3>该版本登记原件</h3><span>${list(r.files).length} 份</span></div><div class="cw-version-files">${list(r.files).map(file=>{const safe=typeof file.url==='string'&&/^\/api\/projects\/[a-f0-9]{12}\/revisions\/[a-f0-9]{16}\/files\/[a-f0-9]{16}$/.test(file.url);return `<div><strong>${esc(file.filename || file.name || '原件')}</strong><small>${esc(file.kind || '')} · SHA256 ${esc(file.sha256 || '未记录')}</small>${safe?`<a class="button button-small" href="${esc(file.url)}" target="_blank" rel="noopener noreferrer">查看原件</a>`:badge('原件链接待核查','amber')}</div>`;}).join('') || '<p class="cw-muted">此版本没有登记可保留的上传原件；来源缺项保持未知。</p>'}</div></section>`;
  }
  function scenarioForm(){
    const stages=[['assembly_start','最终装配投入'],['final_good','最终交付良品'],...list(routes().find(r=>r.id===draft().route_id)?.assembly).map(op=>[op.id,op.name || op.id])];
    const d=draft(), disabled=frozen(), quoteOptions=[['','选择已确认采购报价'],...quotes().map(q=>[q.id,`${q.name || q.part_number || '报价'} · ${q.supplier || '供应商待填'} · ${q.currency || 'CNY'}${q.confirmed?'':' · 待确认'}`])];
    return `<form id="cw-scenario-form" data-context="${esc(key())}"><fieldset ${disabled?'disabled':''}><div class="cw-form-grid">${field(d,'name','方案名称',{required:true,maxLength:120})}${select('revision_id','产品版本',[['','先保存产品版本'],...revisions().map(r=>[r.id,r.label || r.name || r.id])],d.revision_id)}${field(d,'quantity_good','本批交付良品数量（只 / 套）',{type:'number',required:true,min:1,step:1})}${field(d,'as_of','核价日期',{type:'date',required:true})}${select('route_id','所用工艺路线',[['','暂不绑定路线'],...routes().map(r=>[r.id,r.name || r.id])],d.route_id)}</div><div class="cw-section-heading"><div><h3>BOM 与计价方式</h3><p>成品件 / 完整套件按整数用量；自制原料按精确牌号与投料计费。独立模具在工序中按寿命分摊。</p></div><div class="cw-actions">${button('copy-bom','从所选产品版本导入 BOM')}${button('add-line','增加成本项')}</div></div><div class="table-scroll"><table class="cw-lines"><thead><tr><th>物料 / 精确料号</th><th>类别 / 计价方式</th><th>每只 / 套用量 / 投入点</th><th>采购报价</th><th>重量条件</th><th>操作</th></tr></thead><tbody>${d.lines.map(line=>`<tr data-cost-line="${esc(line.id)}"><td><input aria-label="物料名称" name="name" value="${esc(line.name)}" maxlength="200" required><input aria-label="精确料号或图号版本" name="part_number" value="${esc(line.part_number)}" placeholder="精确料号 / 图号版本" maxlength="200"></td><td><select aria-label="物料类别" name="category">${options(Object.entries(categoryLabels),line.category || 'electronic')}</select><select aria-label="自制或外购" name="source_mode">${options([['buy','外购成品'],['make','自制部件原料']],line.source_mode || 'buy')}</select></td><td><input aria-label="每只 / 套用量" name="qty_per_lamp" type="number" min="0.000001" step="any" value="${esc(line.qty_per_lamp)}"><select aria-label="计费投入点" name="consume_at">${options(stages,line.consume_at || (line.category==='packaging'?'final_good':'assembly_start'))}</select></td><td><select aria-label="采购报价" name="quote_id">${options(quoteOptions,line.quote_id || '')}</select><small>${esc(quoteBrief(line.quote_id))}</small></td><td><input aria-label="原材料精确牌号" name="material_part_number" value="${esc(line.material_part_number)}" placeholder="自制原料精确牌号"><input aria-label="净重量克" name="net_weight_g" type="number" min="0" step="any" value="${esc(line.net_weight_g)}" placeholder="净重 g（自制）"><input aria-label="每投入件原料克" name="gross_material_g_per_input_piece" type="number" min="0" step="any" value="${esc(line.gross_material_g_per_input_piece)}" placeholder="每投入件投料 g"></td><td>${button('remove-line','移除',`data-id="${esc(line.id)}"`)}</td></tr>`).join('') || '<tr><td colspan="6" class="cw-table-empty">尚未导入 BOM。也可增加包装、原料或其它采购项。</td></tr>'}</tbody></table></div></fieldset></form>`;
  }
  function quoteBrief(id){const q=quotes().find(row=>row.id===id);return q?`${q.unit || '单位待确认'} · ${q.confirmed?'已确认':'待确认'} · ${taxLabels[q.tax_basis] || '税待确认'} · ${q.valid_until?'有效至 '+q.valid_until:'有效期待确认'}`:'缺报价保持未定价';}
  function coverageForm(){const d=draft();return `<details class="cw-detail"><summary>核价范围确认 <span>防止遗漏 BOM、加工、包装或物流</span></summary><form id="cw-coverage-form"><fieldset ${frozen()?'disabled':''}><div class="cw-coverage-grid">${[['bom','采购 BOM 已覆盖'],['manufacturing','加工路线已覆盖'],['packaging','包装费用已覆盖'],['logistics','物流预算已覆盖']].map(([key,label])=>{const c=d.coverage[key] || {status:'unknown',reason:''};return `<div data-cost-coverage="${key}">${select('status',label,[['unknown','待确认'],['confirmed','已核对范围完整'],['not_applicable','此方案不适用']],c.status)}${field(c,'reason','范围依据 / 不适用原因',{hint:'不适用须填写原因；不能用来隐藏实际费用'})}</div>`;}).join('')}</div></fieldset></form></details>`;}
  function managementForm(){const m=draft().management_fee;return `<details class="cw-detail" ${project()?.sales?.delivery_type==='parts'?'open':''}><summary>工厂管理费用 <span>整灯 / 散件按实际承担范围确认</span></summary><form id="cw-management-form"><fieldset ${frozen()?'disabled':''}><div class="cw-form-grid">${select('status','单列管理费用口径',[['inherit','按所选产品版本的立项口径'],['unknown','待确认是否承担'],['included','单独计入管理费用'],['excluded','不计入管理费用']],m.status)}${m.status==='included'?field(m,'per_unit','每只 / 套管理费用',{type:'number'})+field(m,'currency','费用币种',{maxLength:3})+select('tax_basis','税费口径',Object.entries(taxLabels),m.tax_basis):''}${m.status==='included'||m.status==='excluded'?textarea(m,'reason','费用依据 / 排除原因','不计入须说明原因；已包含在报价中的费用不重复追加。'):''}</div></fieldset></form><p class="cw-muted">保存草稿时读取所选产品版本的交付方式与费用口径。此项单独计费，不改变材料、实际加工 MVA、模具、包装或运费；供应商报价内已包含的费用不自动扣减。</p></details>`;}
  function logisticsForm(){
    const l=draft().logistics || {mode:'none'}, disabled=frozen();let inputs='';
    if(l.mode==='carrier')inputs=field(l,'amount','承运商本批总报价',{type:'number'})+field(l,'valid_until','报价有效至',{type:'date'});
    if(l.mode==='estimate')inputs=field(l,'valid_until','费用有效至',{type:'date'})+field(l,'distance_km','单车单趟公路距离 · km',{type:'number'})+field(l,'loaded_lamps','每趟装载良品灯数',{type:'number',min:1,step:1})+field(l,'fuel_l_per_100km','每百公里油耗 · L',{type:'number'})+field(l,'diesel_per_litre','柴油单价 · 所选币种/L',{type:'number'})+field(l,'tolls','单趟路桥费',{type:'number'})+field(l,'other','单趟其它运输费用',{type:'number'});
    return `<details class="cw-detail" ${l.mode!=='none'?'open':''}><summary>项目物流预算 <span>${esc({none:'暂未计入',carrier:'承运商报价',estimate:'距离与油价分项估算'}[l.mode] || '待确认')}</span></summary><form id="cw-logistics-form"><fieldset ${disabled?'disabled':''}><div class="cw-form-grid">${select('mode','计价方式',[['none','暂未计入（总成本存在缺项）'],['carrier','承运商本批总报价'],['estimate','距离与油价分项估算']],l.mode)}${l.mode!=='none'?field(l,'origin','实际厂门 / 发运地')+field(l,'port','具体目的港区 / 收货点')+field(l,'currency','费用币种',{maxLength:3})+select('tax_basis','原始税费口径',Object.entries(taxLabels),l.tax_basis || 'unknown')+select('shipping_basis','运输费用口径',Object.entries(shipLabels),l.shipping_basis || 'excluded')+inputs+field(l,'source','距离与费用证据来源',{required:true})+textarea(l,'notes','包含项与装载条件','写清燃油、路桥、装卸、返程及港区段是否包含。'):''}</div>${l.mode!=='none'?`<label class="cw-check"><input name="confirmed" type="checkbox" ${l.confirmed?'checked':''}>已确认装载条件、费用来源与包含项</label><details class="cw-detail"><summary>报价中已包含本次运输的 BOM 项</summary><p class="cw-muted">勾选确实已覆盖同一运输段的物料，避免重复加运费。</p>${draft().lines.map(row=>`<label class="cw-check"><input type="checkbox" data-logistics-line="${esc(row.id)}" ${list(l.included_line_ids).includes(row.id)?'checked':''}>${esc(row.name || row.part_number || row.id)}</label>`).join('')}</details>`:''}</fieldset></form><p class="cw-muted">承运商总报价计入本批一次；分项估算按每趟费用 × 向上取整车次，不足一车也计一趟。柴油、路桥和其它费用须使用所选同一币种，系统不自动换汇；缺少承运商基础费用时只代表已填费用。</p></details>`;
  }
  function resultView(){
    const s=scenario(), r=s?.result || s?.calculation || null;
    if(!r)return `<section class="panel cw-result-empty"><h3>计算结果等待完整输入</h3><p>先绑定报价、核对工艺路线和物流条件，然后保存并计算。缺项不会按零价格补齐。</p></section>`;
    const summary=r.summary || r.unit || r;
    const value=(...keys)=>{for(const k of keys)if(finite(summary[k]))return summary[k];return null;};
    const groups=list(r.cost_groups || r.groups), currency=groups.length===1?groups[0].currency:(r.currency || 'CNY'), reviews=list(s.reviews), issues=list(s.issues || r.issues).map(i=>{const review=reviews.find(v=>v.issue_id===i.id);const stale=review?.source_calculated_at&&review.source_calculated_at!==r.calculated_at;return {...i,...(review?{status:stale?'open':i.severity==='blocking'?'open':review.status,assignee:review.owner,due_date:review.due_date,review_opinion:stale?'旧计算的核对记录，请按本次输入重新确认':review.opinion}:{} )};}), complete=r.complete===true || r.status==='complete';
    const procurement=list(r.procurement), sameBasis=procurement.length>0&&new Set(procurement.map(p=>[p.currency,p.tax_basis,p.shipping_basis].join('|'))).size===1;const totalField=f=>sameBasis&&procurement.every(p=>finite(p[f]))?procurement.reduce((sum,p)=>sum+p[f],0):null;
    const metrics=[['生产耗用成本 / 只或套',value('unit_cost','production_consumption_per_lamp','consumption_per_lamp')],['内部加工 MVA / 只或套',value('mva_per_lamp','internal_mva_per_lamp')],['采购现金需求',totalField('procurement_cash')],['超买库存金额',totalField('inventory_value')]];
    return `<section class="panel cw-result"><div class="cw-section-heading"><div><h3>核价结果</h3><p>${esc(r.calculated_at || s.calculated_at || '')} · ${esc(r.calculation_version || r.algorithm_version || '算法版本随快照保存')}</p></div>${badge(complete?'已确认范围可核价':'部分小计 / 待核对',complete?'teal':'amber')}</div><div class="cw-metrics">${metrics.map(([label,v])=>`<div><small>${label}</small><strong>${money(v,label.includes('MVA')?'CNY':label.includes('采购')||label.includes('库存')?procurement[0]?.currency || currency:currency)}</strong></div>`).join('')}</div>${r.notice?note(r.notice,!complete):''}${r.management_fee?note('工厂管理费用：'+({included:'单列计入',excluded:'已排除',unknown:'待确认'}[r.management_fee.status]||'待确认')+' · '+(r.management_fee.reason||'依据待补')):''}${Object.entries(r.coverage || {}).filter(([,c])=>c.status==='not_applicable').map(([scope,c])=>note('本方案排除 '+({bom:'BOM',manufacturing:'加工',packaging:'包装',logistics:'物流'}[scope] || scope)+'：'+(c.reason || '依据待补'))).join('')}${!complete?note('存在未定价、失效报价、未确认费用或口径冲突。以下金额只代表已知部分，不能作为当前交付范围的完整成本。',true):''}${groups.length?`<div class="table-scroll"><table><thead><tr><th>费用分组</th><th>币种 / 税口径</th><th>本批费用</th><th>每只 / 套费用</th></tr></thead><tbody>${groups.map(g=>`<tr><td>${esc(bucketLabels[g.bucket || g.category] || g.name || g.bucket || Object.keys(g.scopes || {}).map(k=>bucketLabels[k] || k).join(' / ') || '已知费用')}</td><td>${esc(g.currency || 'CNY')} · ${esc(taxLabels[g.tax_basis] || g.tax_basis || '待确认')}<small>${esc(shipLabels[g.shipping_basis] || '运费待确认')}</small></td><td>${money(g.total ?? g.amount,g.currency || 'CNY')}</td><td>${money(g.per_lamp ?? g.unit_cost,g.currency || 'CNY')}</td></tr>`).join('')}</tbody></table></div>`:''}${issues.length?issuesView(issues):''}<details class="cw-detail"><summary>采购耗用与批次明细</summary>${costDetailTable(list(r.lines || r.line_results))}${procurementTable(procurement)}${routeResultTable({operations:r.operations})}${logisticsResultView(r.logistics)}</details><div class="cw-actions"><a class="button button-small" href="${esc(scenarioPath(s.id)+'/export')}">导出成本 Excel</a>${s.status==='frozen'?button('actual-open','回填实际结果'):badge('冻结预算后回填实际')}</div></section>`;
  }
  function costDetailTable(rows){return rows.length?`<div class="table-scroll"><table><thead><tr><th>物料</th><th>耗用数量</th><th>采购数量</th><th>超买数量</th><th>耗用费用</th><th>采购金额</th></tr></thead><tbody>${rows.map(row=>`<tr><td>${esc(row.name || row.line_name || row.id)}</td><td>${num(row.required_quantity ?? row.quantity_consumed ?? row.consumption_quantity)}</td><td>${num(row.quantity_purchase ?? row.purchase_quantity)}</td><td>${num(row.quantity_inventory ?? row.inventory_quantity)}</td><td>${money(row.consumption_cost ?? row.amount,row.currency || 'CNY')}</td><td>${money(row.procurement_cash ?? row.purchase_cost,row.currency || 'CNY')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="cw-muted">暂无已计算采购明细。</p>';}
  function procurementTable(rows){return rows.length?`<h4 class="cw-detail-title">按选定报价合并采购</h4><p class="cw-muted">同一采购报价的多行需求合并核算阶梯价、MOQ 与超买库存，采购现金仅在此分组计一次。</p><div class="table-scroll"><table><thead><tr><th>采购料号 / 供应商</th><th>需求 / 单位</th><th>本批采购量</th><th>采购现金</th><th>超买库存</th><th>计价口径</th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.name || p.part_number || p.quote_id || '采购分组')}<small>${esc(p.supplier || '')} · ${esc(p.part_number || '')}</small>${list(p.line_ids).length>1?`<small>关联 ${list(p.line_ids).length} 行 BOM</small>`:''}</td><td>${num(p.required_quantity)} ${esc(p.unit || '')}</td><td>${num(p.purchase_quantity)}</td><td>${money(p.procurement_cash,p.currency || 'CNY')}</td><td>${num(p.inventory_quantity)} ${esc(p.unit || '')}<small>${money(p.inventory_value,p.currency || 'CNY')}</small></td><td>${esc(taxLabels[p.tax_basis] || '税待确认')}<small>${esc(shipLabels[p.shipping_basis] || '运费待确认')}</small></td></tr>`).join('')}</tbody></table></div>`:'';}
  function logisticsResultView(l){if(!l||l.mode==='none')return '';return `<h4 class="cw-detail-title">项目物流预算</h4><div class="table-scroll"><table><thead><tr><th>线路 / 口径</th><th>每趟费用</th><th>所需车次</th><th>本批物流费用</th><th>有效期 / 来源</th></tr></thead><tbody><tr><td>${esc(l.origin)} → ${esc(l.port)}<small>${l.mode==='carrier'?'承运商本批总报价':'每趟分项费用 × 向上取整车次'} · ${esc(taxLabels[l.tax_basis] || '税待确认')}</small></td><td>${l.mode==='carrier'?'按整批报价':money(l.per_trip_cost,l.currency)}</td><td>${l.mode==='carrier'?'不依赖载量分摊':finite(l.trips)?num(l.trips,0):'载量待确认'}</td><td>${money(l.batch_cost,l.currency)}</td><td>${esc(l.valid_until || '有效期待确认')}<small>${esc(l.source)}</small></td></tr></tbody></table></div>`;}
  function routeResultTable(r){const rows=list(r?.operations || r?.steps);return rows.length?`<div class="table-scroll"><table><thead><tr><th>工序</th><th>目标良品</th><th>投入件</th><th>生产小时</th><th>MVA / 批</th></tr></thead><tbody>${rows.map(o=>`<tr><td>${esc(o.name || o.operation_name || o.process_name)}</td><td>${num(o.quantity_good)}</td><td>${num(o.quantity_input)}</td><td>${num(o.production_hours)}</td><td>${money(o.mva ?? o.costs?.mva_internal ?? o.mva_total)}</td></tr>`).join('')}</tbody></table></div>`:'';}
  function issuesView(rows){return `<div class="cw-issues"><div class="cw-section-heading"><h3>工程与核价待办</h3><span>${rows.length} 项</span></div>${rows.map(issue=>`<div class="cw-issue"><div>${badge(issue.status==='resolved'?'已核对':'待核对',issue.status==='resolved'?'teal':'amber')}<strong>${esc(issue.title || issue.message || issue.code || '待核对事项')}</strong><p>${esc(issue.description || issue.detail || '')}</p><small>${esc(issue.assignee || '责任人未分配')}${issue.due_date?' · '+esc(issue.due_date):''}${issue.review_opinion?' · '+esc(issue.review_opinion):''}</small></div>${button('issue-open','记录核对',`data-id="${esc(issue.id || issue.code)}"`)}</div>`).join('')}</div>`;}
  function actualsView(){
    const batches=list(scenario()?.actuals || scenario()?.actual_results);if(!batches.length)return '';
    return `<details class="cw-detail" open><summary>实际记录与预算偏差 <span>${batches.length} 次回填</span></summary>${batches.map(batch=>`<section class="cw-actual-batch"><p class="cw-muted">${esc(batch.created_at || '')} · ${esc(batch.notes || '实际记录保留原口径')}</p><div class="table-scroll"><table><thead><tr><th>类别 / 日期</th><th>实际金额</th><th>范围</th><th>来源</th></tr></thead><tbody>${list(batch.records).map(a=>`<tr><td>${esc(bucketLabels[a.scope] || a.scope)}<small>${esc(a.date)}</small></td><td>${money(a.amount,a.currency || 'CNY')}<small>${esc(taxLabels[a.tax_basis] || '税待确认')} · ${esc(shipLabels[a.shipping_basis] || '运费待确认')}</small></td><td>${a.complete_scope?'已确认完整范围':'部分记录 / 范围待确认'}${a.line_id?`<small>BOM 行 ${esc(a.line_id)}</small>`:''}</td><td>${esc(a.source)}</td></tr>`).join('')}</tbody></table></div><div class="table-scroll"><table><thead><tr><th>对照范围</th><th>预算</th><th>实际</th><th>偏差（实际−预算）</th><th>核对说明</th></tr></thead><tbody>${list(batch.variance).map(v=>`<tr><td>${esc(bucketLabels[v.scope] || v.scope)}</td><td>${money(v.budget,v.currency)}</td><td>${money(v.actual,v.currency)}</td><td>${v.comparable?money(v.delta,v.currency):'不可比'}</td><td>${esc(list(v.reasons).join('；') || '范围与计价口径一致')}</td></tr>`).join('')}</tbody></table></div></section>`).join('')}</details>`;
  }
  function overviewView(){return `${heading('内部核价 · 版本可追溯',project()?.sales?.delivery_type==='parts'?'散件出口成本工作台':'整灯成本工作台','原报价税口径保留；材料、内部 MVA、模具、委外和物流分别核算。')}${toolbar()}${revisionsView()}${revisionDetailView()}<section class="panel cw-editor">${scenarioForm()}${coverageForm()}${managementForm()}${logisticsForm()}<div class="cw-save-bar"><p>${frozen()?'此版本已冻结。复制为新方案后继续修改。':'保存草稿后计算。输入已改动时，旧结果保留供追溯，需重新计算。'}</p><div class="cw-actions">${frozen()?button('fork','复制为新成本方案','',true):button('save','保存草稿')+button('calculate','保存并计算','',true)+button('freeze','冻结所用输入与结果',canFreeze()?'':'disabled')}</div></div></section>${resultView()}${actualsView()}${modalView()}`;}
  function quoteEditorView(){
    const q=quoteEditor;if(!q)return '';
    return `<section class="panel cw-quote-editor">${heading('采购报价','录入已确认报价','按精确料号、供应商和计价单位建档。缺失口径保留待确认。',button('quote-close','关闭'))}<form id="cw-quote-form"><fieldset ${busy?'disabled':''}><div class="cw-form-grid">${field(q,'name','物料 / 服务名称',{required:true})}${field(q,'part_number','精确料号 / 图号版本',{required:true})}${field(q,'supplier','供应商',{required:true})}${select('category','类别',Object.entries(categoryLabels),q.category)}${select('unit','计价单位',[['piece','元件 / 件'],['kg','千克'],['ton','吨'],['set','套']],q.unit)}${field(q,'currency','原报价币种',{required:true,hint:'保留报价币种，不自动换汇',maxLength:3})}${field(q,'unit_price','基础单价',{type:'number',required:true})}${field(q,'moq','最低采购量 MOQ',{type:'number',hint:'不限制请明确填 0'})}${field(q,'order_multiple','订货倍数',{type:'number',min:0.000001})}${select('tax_basis','原报价税费口径',Object.entries(taxLabels),q.tax_basis)}${select('shipping_basis','运费口径',Object.entries(shipLabels),q.shipping_basis)}${field(q,'quoted_at','报价日期',{type:'date',required:true})}${field(q,'valid_until','有效至',{type:'date'})}${field(q,'source','报价证据来源',{required:true,hint:'原报价单、供应商邮件或查询记录'})}${textarea(q,'notes','包含项、质量属性与备注')}</div><details class="cw-detail"><summary>数量阶梯价 <span>${list(q.tiers).length} 档</span></summary><div class="cw-tier-list">${list(q.tiers).map((tier,i)=>`<div data-cost-tier="${i}"><label>起订数量<input name="min_quantity" type="number" min="0" step="any" value="${esc(tier.min_quantity ?? tier.quantity)}"></label><label>该档单价<input name="unit_price" type="number" min="0" step="any" value="${esc(tier.unit_price)}"></label>${button('tier-remove','移除',`data-index="${i}"`)}</div>`).join('')}</div>${button('tier-add','增加阶梯')}</details><div class="cw-actions"><button type="submit" class="button button-primary" ${busy?'disabled':''}>${q.id?'保存报价修订':'确认并入库'}</button></div></fieldset></form></section>`;
  }
  function procurementView(){return `${heading('共享采购依据','采购报价库','精确料号 / 牌号与供应商报价可复用；市场行情用于参考，不自动替代采购价。',button('quote-new','录入采购报价','',true))}<section class="panel cw-import"><div class="cw-section-heading"><div><h3>Excel 导入与字段映射</h3><p>先预览，确认异常与口径后再入库；不会自动采纳所有上传行。</p></div><a class="button button-small" href="/api/supplier-quotes/template">下载报价模板</a></div><label class="cw-upload">${ctx.icon?.('Upload') || ''}<strong>选择真实报价 Excel / CSV</strong><input type="file" id="cw-import-file" accept=".xlsx,.csv,.tsv"></label>${importView()}</section>${quoteEditorView()}<section class="panel"><div class="cw-section-heading"><h3>采购报价记录</h3><span>${quotes().filter(q=>q.confirmed).length} 已确认 / ${quotes().length} 条 · ${button('reload','刷新')}</span></div><div class="table-scroll"><table class="cw-quote-table"><thead><tr><th>物料 / 精确料号</th><th>供应商 / 类别</th><th>单价 / 数量条件</th><th>税运口径</th><th>日期 / 来源</th><th>操作</th></tr></thead><tbody>${quotes().map(q=>`<tr><td><strong>${esc(q.name)}</strong><small>${esc(q.part_number)}</small>${badge(q.confirmed?'人工已确认':'报价待确认',q.confirmed?'teal':'amber')}</td><td>${esc(q.supplier)}<small>${esc(categoryLabels[q.category] || q.category)}</small></td><td>${money(q.unit_price,q.currency || 'CNY')} / ${esc(q.unit)}<small>MOQ ${num(q.moq)} · 倍数 ${num(q.order_multiple)}</small></td><td>${esc(taxLabels[q.tax_basis] || '待确认')}<small>${esc(shipLabels[q.shipping_basis] || '待确认')}</small></td><td>${esc(q.quoted_at || q.rate_date || '')}<small>${q.valid_until?'有效至 '+esc(q.valid_until):'有效期待确认'}</small><small>${esc(q.source)}</small>${list(q.evidence).map(v=>{const url=evidenceUrl(typeof v==='object'?v.url:v);return url?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(v.filename || '查看报价原件')}</a>`:'';}).join('')}</td><td>${button('quote-edit','修订报价',`data-id="${esc(q.id)}"`)}</td></tr>`).join('') || '<tr><td colspan="6" class="cw-table-empty">尚无已确认供应报价。录入真实报价后再绑定到项目成本。</td></tr>'}</tbody></table></div></section>`;}
  function importView(){
    const s=importState;if(!s)return '';const columns=list(s.preview?.columns || s.preview?.headers), rows=list(s.preview?.rows || s.preview?.preview), issues=list(s.preview?.issues || s.preview?.errors);
    return `<div class="cw-import-preview"><p><strong>${esc(s.filename)}</strong> · ${rows.length} 行预览${s.loading?' · 读取中…':''}</p>${s.error?note(s.error,true):''}${columns.length?`<form id="cw-import-mapping" class="cw-form-grid">${['name','part_number','supplier','category','unit_price','unit','currency','tax_basis','shipping_basis','quoted_at','valid_until','source','moq','order_multiple'].map(name=>select(name,{name:'物料名称',part_number:'精确料号',supplier:'供应商',category:'类别',unit_price:'单价',unit:'计价单位',currency:'币种',tax_basis:'税口径',shipping_basis:'运费口径',quoted_at:'报价日期',valid_until:'有效至',source:'证据来源',moq:'MOQ',order_multiple:'订货倍数'}[name],[['','未映射'],...columns.map(c=>[typeof c==='string'?c:c.name,typeof c==='string'?c:c.name])],s.mapping?.[name] || ''))}</form><div class="cw-actions">${button('import-preview','按当前映射重新预览')}</div>`:''}${rows.length?`<div class="table-scroll cw-preview-table"><table><thead><tr><th>选择</th><th>物料 / 料号</th><th>供应商</th><th>单价 / 单位</th><th>核查</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td><input type="checkbox" data-import-row="${i}" aria-label="采纳第 ${r.import_row || i+2} 行" ${s.selected?.has(i)?'checked':''}></td><td>${esc(r.name || r.part_number || list(r.values)[0])}<small>${esc(r.part_number)}</small></td><td>${esc(r.supplier)}</td><td>${esc(r.unit_price)} ${esc(r.currency || '')} / ${esc(r.unit)}</td><td>${esc(list(r.issues || r.errors).map(v=>typeof v==='string'?v:v.message).join('；') || r.status || '待人工核对')}</td></tr>`).join('')}</tbody></table></div>`:''}${issues.length?note(issues.map(i=>typeof i==='string'?i:i.message || JSON.stringify(i)).join('；'),true):''}<label class="cw-check"><input type="checkbox" id="cw-import-confirm" ${s.confirmed?'checked':''}>已核对所选行的料号、价格、日期和税运口径，确认作为采购报价入库</label><div class="cw-actions">${button('import-commit','确认所选行并入库','',true)}${button('import-close','取消导入')}</div></div>`;
  }
  function allOperations(){if(!routeEditor)return [];return [...list(routeEditor.components).flatMap(c=>list(c.operations)),...list(routeEditor.assembly)];}
  function prepareRoute(row){const route=clone(row);for(const op of [...list(route.components).flatMap(c=>list(c.operations)),...list(route.assembly)])op._default_process_name=list(knowledge.processes).find(p=>p.id===op.inputs?.process_id)?.name || '';return route;}
  function findOperation(id){return allOperations().find(o=>o.id===id);}
  function operationContainer(chain){return chain==='assembly'?routeEditor.assembly:routeEditor.components.find(c=>c.line_id===chain)?.operations;}
  function operationView(op,index,chain){
    const d=op.inputs || {}, p=list(knowledge.processes).find(row=>row.id===d.process_id), mode=d.mode || 'cycle';
    const pct={availability_performance_pct:d.availability_performance==null?'':Number(d.availability_performance)*100,yield_rate_pct:d.yield_rate==null?'':Number(d.yield_rate)*100};
    let production=mode==='piece_rate'?field(d,'outsourced_price_per_good_piece','委外加工 · 元 / 交付良品件',{type:'number'}):mode==='throughput'?field(d,'throughput_kg_h','成形产速 · kg/h',{type:'number',min:0.000001})+field(d,'net_weight_g','单件净重量 · g',{type:'number',min:0.000001}):field(d,'cycle_seconds','完整名义周期 · 秒',{type:'number',min:0.000001})+field(d,'cavities','每周期有效产出件数',{type:'number',min:1,step:1});
    if(mode!=='piece_rate')production+=field(pct,'availability_performance_pct','生产效率 · %（不含良率）',{type:'number',min:0.000001})+field(pct,'yield_rate_pct','本工序良率 · %',{type:'number',min:0.000001});
    let rates='';if(mode!=='piece_rate')rates=select('rate_mode','小时费用口径',[['itemized','机时 / 人工 / 电能分项'],['bundled','综合小时加工费']],d.rate_mode || 'itemized')+(d.rate_mode==='bundled'?field(d,'hourly_rate','综合加工费 · 元/h',{type:'number'}):field(d,'machine_rate','纯机时 · 元/h',{type:'number'})+field(d,'operators','分摊作业人数',{type:'number'})+field(d,'labor_rate','人工 · 元/人·h',{type:'number'})+field(d,'average_kw','平均功率 · kW',{type:'number'})+field(d,'electricity_rate','电价 · 元/kWh',{type:'number'}))+field(d,'overhead_rate','额外制造间接费 · 元/h',{type:'number'})+field(d,'consumables_per_input_piece','耗材 · 元/投入件',{type:'number'})+field(d,'setup_hours','额外换型时间 · h',{type:'number'})+field(d,'setup_cost','额外固定换型费 · 元/批',{type:'number'});
    const allowed=list(p?.allowed_modes);const modes=allowed.length?allowed:['cycle','throughput','piece_rate'];
    return `<details class="cw-operation" data-cost-operation="${esc(op.id)}" open><summary><span class="cw-step-number">${index+1}</span><strong>${esc(op.name || p?.name || '新工序')}</strong><span>${esc({cycle:'周期加工',throughput:'连续成形',piece_rate:'委外计件'}[mode])}</span></summary><div class="cw-operation-body"><div class="cw-operation-toolbar"><label class="field">工序名称<input data-operation-name value="${esc(op.name)}" maxlength="200"></label><label class="field">复用已保存单工序条件<select data-cost-select="estimate" data-operation="${esc(op.id)}">${option('','不复用，手工填写','')}${estimates.map(r=>option(r.id,r.name || r.process_name || r.id,'')).join('')}</select></label><div class="cw-actions">${button('operation-up','上移',`data-id="${esc(op.id)}" data-chain="${esc(chain)}"`)}${button('operation-down','下移',`data-id="${esc(op.id)}" data-chain="${esc(chain)}"`)}${button('operation-remove','移除',`data-id="${esc(op.id)}" data-chain="${esc(chain)}"`)}</div></div><div class="cw-form-grid">${select('process_id','工艺类型',list(knowledge.processes).map(p=>[p.id,p.name]),d.process_id)}${select('mode','计算模式',modes.map(m=>[m,{cycle:'完整周期 / 有效产出',throughput:'连续成形产速',piece_rate:'委外良品计件'}[m]]),mode)}${production}${rates}</div><details class="cw-detail"><summary>模具、费率来源与计算条件</summary><div class="cw-form-grid">${field(d,'tooling_total','独立模具待摊价值 · 元',{type:'number',hint:'时率已含或无需分摊时明确填 0'})}${field(d,'tooling_lifetime_good_qty','对应剩余分摊寿命 · 良品件',{type:'number',min:1,step:1})}${field(d,'rate_date','费率依据日期',{type:'date'})}${select('tax_basis','保留原税口径',Object.entries(taxLabels),d.tax_basis || 'unknown')}${field(d,'rate_source','费率 / 生产条件证据来源')}</div></details><p class="cw-muted">不计入的加工费用明确填 0。原料投料由对应 BOM 行计入首工序，工序内不重复加材料；路线统一倒推投入量。</p></div></details>`;
  }
  function captureRoute(){
    const form=$('#cw-route-form');if(!form || !routeEditor)return;
    for(const el of form.elements || [])if(['name','notes'].includes(el.name)&&!el.closest?.('[data-cost-operation]'))routeEditor[el.name]=el.value;
    for(const host of form.querySelectorAll?.('[data-cost-operation]') || []){
      const op=findOperation(host.dataset.costOperation);if(!op)continue;
      const name=host.querySelector?.('[data-operation-name]');if(name)op.name=name.value;
      for(const el of host.querySelectorAll?.('[name]') || []){
        if(el.name==='availability_performance_pct')op.inputs.availability_performance=el.value===''?null:Number(el.value)/100;
        else if(el.name==='yield_rate_pct')op.inputs.yield_rate=el.value===''?null:Number(el.value)/100;
        else op.inputs[el.name]=el.value;
      }
    }
  }
  function routeView(){
    const d=draft(), editor=routeEditor;
    return `${heading('顺序工艺 · 最终装配汇合','工艺路线与整灯 MVA','从交付良品数量（只 / 套）倒推每道工序投入，把后段报废承载的前段耗用计入成本。',button('route-new','建立工艺路线','',true))}${toolbar()}<section class="panel cw-route-library"><div class="cw-section-heading"><h3>本项目已保存路线</h3><a class="button button-small" href="#manufacturing">单工序详细测算</a></div>${routes().length?`<div class="cw-route-cards">${routes().map(r=>`<div class="cw-route-card"><strong>${esc(r.name)}</strong><p>${list(r.components).length} 个部件路线 · ${list(r.assembly).length} 道最终装配工序</p><small>${esc(r.updated_at)}</small><div class="cw-actions">${button('route-edit','读取 / 编辑',`data-id="${esc(r.id)}"`)}${button('route-bind','绑定当前成本草稿',`data-id="${esc(r.id)}"`)}</div></div>`).join('')}</div>`:'<div class="cw-empty-inline">尚无路线。先在成本总览定义 BOM，并将需加工的部件设为自制。</div>'}</section>${editor?`<section class="panel cw-route-editor">${heading('路线编辑',editor.id?'修订工艺路线':'新建工艺路线','保存路线不改写已冻结成本快照。修改后需重新计算成本。',button('route-close','关闭'))}<form id="cw-route-form"><fieldset ${busy?'disabled':''}><div class="cw-form-grid">${field(editor,'name','路线名称',{required:true,maxLength:200})}${textarea(editor,'notes','路线依据与边界')}</div>${list(editor.components).map(c=>{const line=d.lines.find(l=>l.id===c.line_id);return `<section class="cw-chain"><div class="cw-section-heading"><div><p class="eyebrow">自制部件</p><h3>${esc(line?.name || c.line_id)}</h3><p>${esc(line?.part_number || '料号待填')} · 每灯 ${esc(line?.qty_per_lamp ?? '待确认')} 件</p></div><div class="cw-actions">${button('operation-add','增加工序',`data-chain="${esc(c.line_id)}"`)}${button('component-remove','移除部件路线',`data-id="${esc(c.line_id)}"`)}</div></div>${list(c.operations).map((op,i)=>operationView(op,i,c.line_id)).join('') || '<p class="cw-muted">本部件还没有加工工序。</p>'}</section>`;}).join('')}<div class="cw-component-picker"><label class="field">增加自制部件路线<select id="cw-component-line">${option('','选择成本 BOM 的自制部件','')}${d.lines.filter(l=>l.source_mode==='make'&&!editor.components.some(c=>c.line_id===l.id)).map(l=>option(l.id,l.name || l.part_number || l.id,'')).join('')}</select></label>${button('component-add','增加部件路线')}</div><section class="cw-chain cw-assembly"><div class="cw-section-heading"><div><p class="eyebrow">最终汇合</p><h3>整灯装配、测试与包装</h3><p>以最终良品灯为产出，良率向前传递至各部件。</p></div>${button('operation-add','增加最终装配工序','data-chain="assembly"')}</div>${list(editor.assembly).map((op,i)=>operationView(op,i,'assembly')).join('') || '<p class="cw-muted">尚未录入最终装配工序；不默认零费用。</p>'}</section><div class="cw-save-bar"><p>首版为顺序路线；返工循环、联产品和跨型号共享资源需要另行核实。</p><button type="submit" class="button button-primary" ${busy?'disabled':''}>保存工艺路线</button></div></fieldset></form></section>`:note('选择一条保存路线或建立新路线。所有费率与良率均使用工厂资料，不预置参考价格。')}`;
  }
  function compareView(){const records=scenarios().filter(s=>s.status==='frozen'), result=compareResult;return `${heading('方案决策 · 性能与成本同时核对','比较降本方案','比较同一产品条件的冻结成本版本。成本降低不会自动确认材料替代或工程适用。')}<section class="panel"><form id="cw-compare-form" class="cw-compare-form">${select('left','基准方案',[['','选择已冻结基准'],...records.map(r=>[r.id,r.name])],result?.left_id || '')}${select('right','候选方案',[['','选择已冻结候选'],...records.map(r=>[r.id,r.name])],result?.right_id || '')}<button type="submit" class="button button-primary" ${busy?'disabled':''}>比较方案</button></form>${records.length<2?note('至少冻结两个成本方案后比较。草稿可持续补资料，冻结保存所用输入与来源。'):''}</section>${result?`<section class="panel cw-comparison"><div class="cw-section-heading"><h3>比较结果</h3>${badge(result.compatible?'计价条件可比':'条件不兼容',result.compatible?'teal':'amber')}</div>${result.compatible?`<div class="cw-metrics"><div><small>候选方案每灯减少</small><strong>${money(result.unit_savings,result.currency || list(scenarios().find(s=>s.id===result.left_id)?.result?.groups)[0]?.currency || 'CNY')}</strong></div><div><small>本批费用减少</small><strong>${money(result.total_savings,result.currency || list(scenarios().find(s=>s.id===result.left_id)?.result?.groups)[0]?.currency || 'CNY')}</strong></div></div>`:note(list(result.reasons).join('；') || '数量、币种、税运口径或缺项使两个方案不能形成确定节省结论。',true)}${result.notice?note(result.notice):''}<div class="table-scroll"><table><thead><tr><th>变化项目</th><th>基准</th><th>候选</th><th>差额</th></tr></thead><tbody>${list(result.differences).map(row=>`<tr><td>${esc(bucketLabels[row.scope] || ({mva_total:'整批内部 MVA',total_cost:'本批总成本',unit_cost:'每灯成本'}[row.scope]) || row.name || row.scope)}</td><td>${finite(row.left)?money(row.left,row.left_currency || row.currency || result.currency || '币种待确认'):esc(row.left ?? '未知')}</td><td>${finite(row.right)?money(row.right,row.right_currency || row.currency || result.currency || '币种待确认'):esc(row.right ?? '未知')}</td><td>${result.compatible?money(row.delta,row.currency || result.currency || '币种待确认'):'不可比'}</td></tr>`).join('')}</tbody></table></div><div class="cw-engineering-checks"><h3>替代方案工程核查</h3>${list(result.engineering_checks).map(check=>`<p>${ctx.icon?.('ClipboardCheck') || ''}${esc(typeof check==='string'?check:check.message || check.title || check.name || (list(check.requirements).join('、')+' · '+(check.notice || '待工程核对')))}</p>`).join('') || '<p>核对光学、热、阻燃、可靠性和目标国准入证据后，才能采用替代方案。</p>'}</div></section>`:''}`;}
  function modalView(){
    if(actualEditor)return `<section class="panel cw-actual-editor">${heading('实际结果','回填实际记录','生产耗用与采购结算分开。保留原币种、税运口径和账单来源。',button('actual-close','关闭'))}<form id="cw-actual-form"><div class="cw-form-grid">${select('scope','实际类别',[['consumption','实际生产耗用'],['procurement','实际采购支出'],['manufacturing','实际内部加工费用'],['logistics','实际物流支出'],['factory_management','实际工厂管理费用']],actualEditor.scope)}${field(actualEditor,'amount','实际本批金额',{type:'number',required:true})}${field(actualEditor,'currency','原币种',{maxLength:3,required:true})}${select('tax_basis','税口径',Object.entries(taxLabels),actualEditor.tax_basis)}${select('shipping_basis','运费口径',Object.entries(shipLabels),actualEditor.shipping_basis)}${field(actualEditor,'date','账单 / 记录日期',{type:'date',required:true})}${field(actualEditor,'quantity','实际数量（可选）',{type:'number'})}${select('unit','数量单位',[['batch','批'],['lamp','灯'],['piece','件'],['kg','kg'],['ton','吨'],['set','套'],['hour','小时']],actualEditor.unit || 'batch')}${select('line_id','实际覆盖的 BOM 行',[['','所选费用类别的全部范围'],...draft().lines.map(l=>[l.id,l.name || l.part_number || l.id])],actualEditor.line_id || '')}${field(actualEditor,'source','结算单 / 生产记录来源',{required:true})}</div><label class="cw-check"><input name="complete_scope" type="checkbox" ${actualEditor.complete_scope?'checked':''}>此记录覆盖所选范围的完整实际金额，已核对未遗漏账单或耗用</label><button type="submit" class="button button-primary" ${busy?'disabled':''}>保存实际结果</button></form></section>`;
    if(issueEditor)return `<section class="panel cw-issue-editor">${heading('待办核对',issueEditor.title || '记录责任人与工程意见','记录处理进展不自动补齐缺失价格，也不自动批准替代方案。',button('issue-close','关闭'))}<form id="cw-issue-form"><div class="cw-form-grid">${field(issueEditor,'owner','责任人')}${field(issueEditor,'due_date','计划完成日期',{type:'date'})}${select('status','处理状态',[['open','待核对'],['in_progress','处理中'],['resolved','已核对并记录意见']],issueEditor.status)}${textarea(issueEditor,'evidence','核对证据')}${textarea(issueEditor,'opinion','工程 / 核价确认意见')}</div><button type="submit" class="button button-primary" ${busy?'disabled':''}>保存核对记录</button></form></section>`;return '';
  }
  function view(){if(!projectId)return emptyProject();return `<div class="cost-workbench" aria-label="项目成本核算">${error?note(error+'。已输入内容保留，请核对后重试。',true):''}${busy?'<div class="cw-busy" role="status">正在处理，请稍候…</div>':''}${!workspace&&error?`<section class="panel cw-empty"><h2>成本资料暂未读取</h2>${button('reload','重新读取','',true)}</section>`:tab==='procurement'?procurementView():tab==='route'?routeView():tab==='compare'?compareView():overviewView()}</div>`;}
  function numeric(value,label,{optional=false,positive=false,integer=false}={}){if(value==='' || value==null){if(optional)return null;throw new Error(`请填写${label}；零费用须明确填 0`);}const n=Number(value);if(!Number.isFinite(n)||n<0||(positive&&n<=0)||(integer&&!Number.isInteger(n)))throw new Error(`${label}须为有效${integer?'整数':'数字'}`);return n;}
  const id=prefix=>prefix+'-'+Math.random().toString(36).slice(2,10)+'-'+Date.now().toString(36);
  function cleanLogistics(l){
    const result={mode:l.mode || 'none',currency:l.currency || 'CNY',tax_basis:l.tax_basis || 'unknown',shipping_basis:l.shipping_basis || 'excluded',source:l.source || '',origin:l.origin || '',port:l.port || '',valid_until:l.valid_until || null,notes:l.notes || '',confirmed:l.confirmed===true,included_line_ids:list(l.included_line_ids)};
    if(result.mode==='carrier')result.amount=numeric(l.amount,'承运商本批总报价',{optional:true});
    if(result.mode==='estimate'){for(const f of ['distance_km','fuel_l_per_100km','diesel_per_litre','tolls','other'])result[f]=numeric(l[f],f,{optional:true});result.loaded_lamps=numeric(l.loaded_lamps,'每趟装载灯数',{optional:true,positive:true,integer:true});if(list(l.legs).length)result.legs=clone(l.legs);}
    return result;
  }
  function scenarioPayload(source=null,capture=true){
    if(capture)remember();const d=source || draft();if(!String(d.name).trim())throw new Error('请填写成本方案名称');if(!d.revision_id)throw new Error('请先保存并选择产品版本');
    const p={project_id:projectId,name:String(d.name).trim(),revision_id:d.revision_id,quantity_good:numeric(d.quantity_good,'交付良品数量（只 / 套）',{positive:true,integer:true}),as_of:d.as_of,route_id:d.route_id || null,logistics:cleanLogistics(d.logistics),coverage:clone(d.coverage),lines:d.lines.map(row=>({id:row.id,name:row.name || '',part_number:row.part_number || '',category:row.category || 'electronic',source_mode:row.source_mode || 'buy',material_part_number:row.material_part_number || '',consume_at:row.consume_at || (row.category==='packaging'?'final_good':'assembly_start'),qty_per_lamp:numeric(row.qty_per_lamp,'每只 / 套用量',{positive:true,integer:row.source_mode!=='make'&&['piece','set'].includes(quotes().find(q=>q.id===row.quote_id)?.unit)}),quote_id:row.quote_id || null,net_weight_g:numeric(row.net_weight_g,'净重量',{optional:true,positive:true}),gross_material_g_per_input_piece:row.source_mode==='make'?numeric(row.gross_material_g_per_input_piece,'投料重量',{optional:true,positive:true}):null,notes:row.notes || '',engineering_status:row.engineering_status || 'unknown'}))};
    const m=d.management_fee;if(m&&m.status!=='inherit')p.management_fee={status:m.status,per_unit:m.status==='excluded'?0:numeric(m.per_unit,'每只 / 套管理费用',{optional:true}),currency:m.currency||'CNY',tax_basis:m.tax_basis||'unknown',reason:m.reason||''};
    if(scenario()?.updated_at)p.expected_updated_at=scenario().updated_at;return p;
  }
  function canFreeze(){const s=scenario();if(!s?.id||!s.result||s.status==='frozen'||busy)return false;try{return JSON.stringify(scenarioPayload(null,false))===JSON.stringify(scenarioPayload(initialDraft(s),false));}catch{return false;}}
  function updateFreezeControl(){const control=$('[data-cost-action="freeze"]');if(control)control.disabled=!canFreeze();}
  function captureTiers(){if(!quoteEditor)return;const hosts=$('#cw-quote-form')?.querySelectorAll?.('[data-cost-tier]');if(!hosts)return;quoteEditor.tiers=[...hosts].map(h=>({min_quantity:h.querySelector?.('[name="min_quantity"]')?.value ?? '',unit_price:h.querySelector?.('[name="unit_price"]')?.value ?? ''}));}
  function quotePayload(){remember();const q=quoteEditor;if(!q)throw new Error('报价表单未打开');return {name:q.name || '',part_number:q.part_number || '',supplier:q.supplier || '',category:q.category || 'electronic',unit:q.unit || 'piece',currency:String(q.currency || 'CNY').toUpperCase(),unit_price:numeric(q.unit_price,'单价'),moq:numeric(q.moq,'MOQ',{optional:true}),order_multiple:numeric(q.order_multiple,'订货倍数',{optional:true,positive:true}),tax_basis:q.tax_basis || 'unknown',shipping_basis:q.shipping_basis || 'unknown',quoted_at:q.quoted_at || null,valid_until:q.valid_until || null,source:q.source || '',notes:q.notes || '',confirmed:true,tiers:list(q.tiers).map(t=>({min_quantity:numeric(t.min_quantity,'阶梯起订数量'),unit_price:numeric(t.unit_price,'阶梯单价')})),evidence:list(q.evidence),...(q.id?{id:q.id,expected_updated_at:q.updated_at}:{} )};}
  function routePayload(){
    remember();const r=routeEditor;if(!r)throw new Error('路线表单未打开');
    const operation=op=>{const d=op.inputs || {}, time=d.mode!=='piece_rate';let inputs={process_id:d.process_id,mode:d.mode || 'cycle',currency:'CNY',tax_basis:d.tax_basis || 'unknown',rate_date:d.rate_date || '',rate_source:d.rate_source || ''};
      const optional=new Set(['tooling_lifetime_good_qty']);let fields=['tooling_total'];
      if(Number(d.tooling_total)>0)fields.push('tooling_lifetime_good_qty');
      if(time){fields.push('availability_performance','yield_rate','overhead_rate','consumables_per_input_piece','setup_hours','setup_cost');inputs.rate_mode=d.rate_mode || 'itemized';fields.push(...(inputs.rate_mode==='bundled'?['hourly_rate']:['machine_rate','operators','labor_rate','average_kw','electricity_rate']));fields.push(...(inputs.mode==='throughput'?['throughput_kg_h','net_weight_g']:['cycle_seconds','cavities']));}
      else fields.push('outsourced_price_per_good_piece');
      for(const f of fields)inputs[f]=numeric(d[f],`${op.name || '工序'}：${f}`,{optional:true,positive:['cycle_seconds','cavities','availability_performance','yield_rate','throughput_kg_h','net_weight_g','tooling_lifetime_good_qty'].includes(f),integer:['cavities','tooling_lifetime_good_qty'].includes(f)});
      if(time&&(inputs.yield_rate>1||inputs.availability_performance>1))throw new Error('工序效率和良率须大于 0 且不超过 100%');
      return {id:op.id,name:op.name || '',inputs};};
    return {project_id:projectId,name:r.name || '',notes:r.notes || '',components:list(r.components).map(c=>({line_id:c.line_id,operations:list(c.operations).map(operation)})),assembly:list(r.assembly).map(operation),...(r.id?{id:r.id,expected_updated_at:r.updated_at}:{} )};
  }
  function applyScenario(row){if(!row || !row.id)throw new Error('未返回有效成本方案，请重新读取');workspace.scenarios=[row,...scenarios().filter(s=>s.id!==row.id)];selected=row.id;selectedByProject.set(projectId,selected);drafts.set(key(),initialDraft(row));}
  async function run(task,success=''){
    if(!active||busy)return null;remember();const token=epoch,pid=projectId;busy=true;error='';paint();
    try{const value=await task(()=>active&&token===epoch&&pid===projectId);if(!active||token!==epoch||pid!==projectId)return null;if(success)ctx.toast?.(success);return value;}
    catch(err){if(active&&token===epoch&&pid===projectId){error=err.message || '操作未完成';ctx.toast?.(error,true);}return null;}
    finally{if(active&&token===epoch&&pid===projectId){busy=false;paint();}}
  }
  async function saveScenario(calculate=false){
    if(frozen())return;let payload;try{payload=scenarioPayload();}catch(err){error=err.message;paint();return;}
    await run(async()=>{const pid=projectId, token=epoch, existing=selected;let row=await ctx.api(existing?scenarioPath(existing):base()+'/cost-scenarios','POST',payload);if(token!==epoch||pid!==projectId||!active)return;applyScenario(row);if(calculate){row=await ctx.api(scenarioPath(row.id)+'/calculate','POST',{expected_updated_at:row.updated_at});if(token!==epoch||pid!==projectId||!active)return;applyScenario(row);}return row;},calculate?'核价计算已保存':'成本草稿已保存');
  }
  function newOperation(chain=''){const processes=list(knowledge.processes),p=chain==='assembly'?(processes.find(p=>p.id==='assembly_testing') || processes.find(p=>p.id==='assembly' || /装配.*测试/.test(p.name)) || processes[0]):processes[0];return {id:id('op'),name:p?.name || '',_default_process_name:p?.name || '',inputs:{process_id:p?.id || '',mode:p?.preferred_mode || p?.allowed_modes?.[0] || 'cycle',rate_mode:'itemized',tax_basis:'unknown',rate_date:'',rate_source:''}};}
  async function refreshWorkspace(){const token=epoch,pid=projectId,value=await ctx.api(base()+'/cost-workspace');if(token!==epoch||pid!==projectId||!active)return;workspace=value;if(selected){const full=await ctx.api(base()+'/cost-scenarios/'+encodeURIComponent(selected));if(token===epoch&&pid===projectId&&active)workspace.scenarios=scenarios().map(row=>row.id===full.id?full:row);}}
  async function readUpload(file){if(!file)return;if(file.size>20*1024*1024){error='报价文件不得超过 20MB';paint();return;}importState={filename:file.name,content_base64:'',mapping:{},preview:null,selected:new Set(),confirmed:false,error:'',loading:true};const state=importState;await run(async()=>{const content=await ctx.base64File(file);if(importState!==state)return;state.content_base64=content;const result=await ctx.api('/api/supplier-quotes/preview','POST',{filename:state.filename,content_base64:content});if(importState!==state)return;state.preview=result;state.mapping=result.mapping || {};state.loading=false;},'预览已读取，请核对字段与异常');if(importState===state)state.loading=false;paint();}
  async function previewImport(){if(!importState)return;const s=importState;for(const el of $('#cw-import-mapping')?.elements || [])if(el.name)s.mapping[el.name]=el.value;s.mapping=Object.fromEntries(Object.entries(s.mapping).filter(([,v])=>v));await run(async()=>{const r=await ctx.api('/api/supplier-quotes/preview','POST',{filename:s.filename,content_base64:s.content_base64,mapping:s.mapping});if(importState===s){s.preview=r;s.mapping=r.mapping || s.mapping;s.selected=new Set();s.confirmed=false;}});}
  async function commitImport(){const s=importState;if(!s)return;const mappingForm=$('#cw-import-mapping');if(mappingForm){const mapping={};for(const el of mappingForm.elements || [])if(el.name&&el.value)mapping[el.name]=el.value;if(JSON.stringify(Object.entries(mapping).sort())!==JSON.stringify(Object.entries(s.preview?.mapping || {}).sort())){error='字段映射已改变，请重新预览并核对后导入';paint();return;}}const confirm=$('#cw-import-confirm');if(confirm)s.confirmed=confirm.checked;if(!s.confirmed){error='请先确认已核对所选报价的内容与计价口径';paint();return;}const selectedRows=list(s.preview?.rows).filter((r,i)=>s.selected.has(i)).map(r=>r.import_row);if(!selectedRows.length){error='请至少选择一条已核对的报价';paint();return;}await run(async current=>{await ctx.api('/api/supplier-quotes/import','POST',{preview_id:s.preview.preview_id || s.preview.id,confirmed:true,confirm_quotes:true,selected_rows:selectedRows});if(!current())return;await refreshWorkspace();if(importState===s)importState=null;},'所选采购报价已确认入库');}
  async function submitRevision(form){const label=form.elements?.label?.value || '';if(!label.trim()){error='请填写产品版本名称';paint();return;}await run(async()=>{await ctx.api(base()+'/revisions','POST',{label:label.trim(),expected_updated_at:project()?.updated_at});await refreshWorkspace();},'当前产品版本已保存');}
  async function submitQuote(){let payload;try{payload=quotePayload();}catch(err){error=err.message;paint();return;}const editor=quoteEditor;await run(async()=>{await ctx.api('/api/supplier-quotes','POST',payload);await refreshWorkspace();if(quoteEditor===editor)quoteEditor=null;},'采购报价已确认保存');}
  async function submitRoute(){let payload;try{payload=routePayload();}catch(err){error=err.message;paint();return;}const editor=routeEditor;await run(async()=>{const row=await ctx.api(base()+'/process-routes','POST',payload);await refreshWorkspace();if(routeEditor===editor)routeEditor=prepareRoute(row);},'工艺路线已保存，请重新计算关联成本');}
  async function submitCompare(form){const left=form.elements?.left?.value,right=form.elements?.right?.value;if(!left||!right||left===right){error='请选择两个不同的冻结成本方案';paint();return;}await run(async current=>{const r=await ctx.api(base()+'/cost-scenarios/compare?left='+encodeURIComponent(left)+'&right='+encodeURIComponent(right));if(current())compareResult=r;});}
  async function submitActual(){remember();const d=actualEditor;if(!d||!selected)return;let record;try{record={scope:d.scope,amount:numeric(d.amount,'实际金额'),currency:String(d.currency || 'CNY').toUpperCase(),tax_basis:d.tax_basis || 'unknown',shipping_basis:d.shipping_basis || 'unknown',date:d.date,source:d.source || '',line_id:d.line_id || '',complete_scope:d.complete_scope===true};if(d.quantity!==''&&d.quantity!=null)record.quantity=numeric(d.quantity,'实际数量');record.unit=d.unit || 'batch';}catch(err){error=err.message;paint();return;}const sid=selected;await run(async()=>{await ctx.api(scenarioPath(sid)+'/actuals','POST',{records:[record]});await refreshWorkspace();if(selected===sid)actualEditor=null;},'实际结果已保存');}
  async function submitIssue(){remember();const d=issueEditor;if(!d||!selected)return;const sid=selected;await run(async()=>{await ctx.api(scenarioPath(sid)+'/issues/'+encodeURIComponent(d.id),'POST',{owner:d.owner || '',due_date:d.due_date || null,evidence:d.evidence || '',opinion:d.opinion || '',status:d.status || 'open',...(d.updated_at?{expected_updated_at:d.updated_at}:{})});await refreshWorkspace();if(selected===sid)issueEditor=null;},'核对记录已保存');}
  async function action(name,extra={}){
    if(!active||busy)return;remember();error='';
    if(name==='reload'){await load(projectId,tab);paint();return;}
    if(name==='new'){selected='';selectedByProject.set(projectId,'');drafts.set(key(),initialDraft(null));paint();return;}
    if(name==='save'||name==='calculate'){await saveScenario(name==='calculate');return;}
    if(name==='freeze'){
      const s=scenario();if(!s?.result){error='请先保存并计算成本，再冻结所用输入';paint();return;}
      if(JSON.stringify(scenarioPayload())!==JSON.stringify(scenarioPayload(initialDraft(s),false))){error='输入已变更，请先保存并重新计算后冻结';paint();return;}
      await run(async current=>{const row=await ctx.api(scenarioPath(s.id)+'/freeze','POST',{expected_updated_at:s.updated_at});if(current())applyScenario(row);},'成本版本已冻结，工程确认仍须单独核对');return;
    }
    if(name==='fork'){const s=scenario();if(!s)return;await run(async current=>{const row=await ctx.api(scenarioPath(s.id)+'/fork','POST',{expected_updated_at:s.updated_at});if(current())applyScenario(row);},'已建立可编辑的新成本方案');return;}
    if(name==='add-line'&&!frozen()){draft().lines.push({id:id('line'),name:'',part_number:'',category:'electronic',source_mode:'buy',qty_per_lamp:'',quote_id:'',net_weight_g:'',gross_material_g_per_input_piece:'',material_part_number:'',consume_at:''});paint();return;}
    if(name==='remove-line'&&!frozen()){draft().lines=draft().lines.filter(row=>row.id!==extra.id);paint();return;}
    if(name==='copy-bom'&&!frozen()){
      const revision=revisions().find(r=>r.id===draft().revision_id);if(!revision){error='请先选择一个保存的产品版本';paint();return;}
      let full=revision;if(!Array.isArray(revision.bom)&&!revision.snapshot){const value=await run(()=>ctx.api(base()+'/revisions/'+encodeURIComponent(revision.id)));if(!value)return;full=value;}
      const input=full.snapshot || full.project || full;const bom=list(input.bom);if(!bom.length){error='所选产品版本没有 BOM。请先上传或整理真实 BOM';paint();return;}
      const added=bom.map(row=>({id:id('line'),name:row.name || row.description || '',part_number:row.part_number || row.lcsc_part || row.mpn || row.model || '',category:Object.hasOwn(categoryLabels,row.category)?row.category:'electronic',source_mode:'buy',qty_per_lamp:row.qty_per_lamp ?? row.quantity ?? row.qty ?? '',quote_id:'',net_weight_g:'',gross_material_g_per_input_piece:'',material_part_number:'',consume_at:row.category==='packaging'?'final_good':'assembly_start',notes:input.bom_source==='generated_demo'||row.source_type==='generated_demo'?'历史生成样例，仅用于结构参考，不能作为真实工程依据':''}));draft().lines.push(...added);if(input.bom_source==='generated_demo')error='此 BOM 来自历史生成样例，只导入逻辑结构；请替换为真实项目 BOM 并确认来源';paint();return;
    }
    if(name==='revision-open'){await run(async current=>{const row=await ctx.api(base()+'/revisions/'+encodeURIComponent(extra.id));if(current())revisionDetail=row;});return;}
    if(name==='revision-close'){revisionDetail=null;paint();return;}
    if(name==='quote-new'){quoteEditor={name:'',part_number:'',supplier:'',category:'electronic',unit:'piece',currency:'CNY',unit_price:'',moq:'',order_multiple:'',tax_basis:'unknown',shipping_basis:'unknown',quoted_at:'',valid_until:'',source:'',notes:'',tiers:[],evidence:[]};paint();return;}
    if(name==='quote-edit'){const q=quotes().find(q=>q.id===extra.id);if(q)quoteEditor=clone(q);paint();return;}
    if(name==='quote-close'){quoteEditor=null;paint();return;}
    if(name==='tier-add'&&quoteEditor){quoteEditor.tiers.push({min_quantity:'',unit_price:''});paint();return;}
    if(name==='tier-remove'&&quoteEditor){quoteEditor.tiers.splice(Number(extra.index),1);paint();return;}
    if(name==='import-preview'){await previewImport();return;}
    if(name==='import-commit'){await commitImport();return;}
    if(name==='import-close'){importState=null;paint();return;}
    if(name==='route-new'){routeEditor={name:'',notes:'',components:[],assembly:[]};paint();return;}
    if(name==='route-edit'){const r=routes().find(r=>r.id===extra.id);if(r)routeEditor=prepareRoute(r);paint();return;}
    if(name==='route-close'){routeEditor=null;paint();return;}
    if(name==='route-bind'){if(frozen()){error='冻结版本需先复制为新方案';paint();return;}draft().route_id=extra.id;ctx.toast?.('路线已绑定草稿，保存并计算后生效');paint();return;}
    if(name==='component-add'&&routeEditor){const lineId=$('#cw-component-line')?.value;if(!lineId){error='请选择自制 BOM 部件';paint();return;}if(!routeEditor.components.some(c=>c.line_id===lineId))routeEditor.components.push({line_id:lineId,operations:[]});paint();return;}
    if(name==='component-remove'&&routeEditor){routeEditor.components=routeEditor.components.filter(c=>c.line_id!==extra.id);paint();return;}
    if(name==='operation-add'&&routeEditor){operationContainer(extra.chain)?.push(newOperation(extra.chain));paint();return;}
    if(['operation-up','operation-down','operation-remove'].includes(name)&&routeEditor){const rows=operationContainer(extra.chain),i=rows?.findIndex(o=>o.id===extra.id);if(rows&&i>=0){if(name==='operation-remove')rows.splice(i,1);else{const target=name==='operation-up'?i-1:i+1;if(target>=0&&target<rows.length)[rows[i],rows[target]]=[rows[target],rows[i]];}}paint();return;}
    if(name==='actual-open'&&selected&&frozen()){actualEditor={scope:'consumption',amount:'',currency:'CNY',tax_basis:'unknown',shipping_basis:'unknown',date:'',source:'',quantity:'',unit:'batch',line_id:'',complete_scope:false};paint();return;}
    if(name==='actual-close'){actualEditor=null;paint();return;}
    if(name==='issue-open'){const s=scenario(),i=list(s?.result?.issues).find(i=>(i.id || i.code)===extra.id), review=list(s?.reviews).find(r=>r.issue_id===extra.id), stale=review?.source_calculated_at&&review.source_calculated_at!==s?.result?.calculated_at;if(i)issueEditor={id:extra.id,updated_at:review?.updated_at || '',title:i.title || i.message,owner:review?.owner || '',due_date:review?.due_date || '',status:stale?'open':review?.status || 'open',evidence:review?.evidence || '',opinion:review?.opinion || ''};paint();return;}
    if(name==='issue-close'){issueEditor=null;paint();}
  }
  document.addEventListener('click',async event=>{const b=event.target?.closest?.('[data-cost-action]');if(!b||!active||b.disabled)return;await action(b.dataset.costAction,b.dataset);});
  document.addEventListener('submit',async event=>{if(!active||busy)return;const handlers={'cw-revision-form':submitRevision,'cw-quote-form':submitQuote,'cw-route-form':submitRoute,'cw-compare-form':submitCompare,'cw-actual-form':submitActual,'cw-issue-form':submitIssue};const handler=handlers[event.target?.id];if(handler){event.preventDefault();await handler(event.target);}});
  document.addEventListener('input',event=>{if(!active||busy)return;if(event.target?.closest?.('#cw-scenario-form,#cw-logistics-form,#cw-coverage-form,#cw-management-form,#cw-quote-form,#cw-route-form,#cw-actual-form,#cw-issue-form')){remember();updateFreezeControl();}});
  document.addEventListener('change',async event=>{
    if(!active||busy)return;const target=event.target;if(target?.id==='cw-import-file'){await readUpload(target.files?.[0]);return;}
    if(target?.dataset?.importRow!=null&&importState){const i=Number(target.dataset.importRow);target.checked?importState.selected.add(i):importState.selected.delete(i);return;}
    if(target?.id==='cw-import-confirm'&&importState){importState.confirmed=target.checked;return;}
    if(target?.dataset?.logisticsLine){const l=draft().logistics;const ids=new Set(list(l.included_line_ids));target.checked?ids.add(target.dataset.logisticsLine):ids.delete(target.dataset.logisticsLine);l.included_line_ids=[...ids];return;}
    if(target?.dataset?.costSelect==='scenario'){remember();selected=target.value;selectedByProject.set(projectId,selected);draft();actualEditor=null;issueEditor=null;paint();return;}
    if(target?.dataset?.costSelect==='estimate'){captureRoute();const op=findOperation(target.dataset.operation),record=estimates.find(r=>r.id===target.value);if(op&&record){const source=clone(record.inputs || record.result?.inputs || {});for(const f of ['name','quantity_good','qty_per_lamp','project_id','material_price_per_kg','gross_material_g_per_input_piece','recoverable_scrap_g_per_input_piece','scrap_credit_per_kg'])delete source[f];op.inputs=source;op.name=record.name || op.name;op._default_process_name=list(knowledge.processes).find(p=>p.id===source.process_id)?.name || '';ctx.toast?.('已复用单工序条件，原料和目标数量由路线统一计算');paint();}return;}
    if(target?.closest?.('#cw-management-form')&&target.name==='status'){remember();if(target.value==='excluded')draft().management_fee.per_unit=0;paint();return;}
    if(target?.closest?.('#cw-logistics-form')&&target.name==='mode'){remember();const old=draft().logistics;draft().logistics={mode:target.value,currency:old.currency || 'CNY',tax_basis:old.tax_basis || 'unknown',shipping_basis:old.shipping_basis || 'excluded',source:old.source || '',origin:old.origin || '',port:old.port || '',notes:old.notes || '',confirmed:false,included_line_ids:[]};paint();return;}
    if(target?.closest?.('[data-cost-operation]')&&['process_id','mode','rate_mode'].includes(target.name)){captureRoute();const op=findOperation(target.closest('[data-cost-operation]').dataset.costOperation);if(op&&target.name==='process_id'){const process=list(knowledge.processes).find(p=>p.id===op.inputs.process_id);if(!op.name||op.name===op._default_process_name)op.name=process?.name || op.name;op._default_process_name=process?.name || '';op.inputs.mode=process?.preferred_mode || process?.allowed_modes?.[0] || 'cycle';}paint();return;}
    if(target?.closest?.('[data-cost-line]')&&target.name==='consume_at'){remember();const line=draft().lines.find(r=>r.id===target.closest('[data-cost-line]').dataset.costLine);if(line)line._consume_at_explicit=true;return;}
    if(target?.closest?.('[data-cost-line]')&&target.name==='category'){remember();const line=draft().lines.find(r=>r.id===target.closest('[data-cost-line]').dataset.costLine);if(line&&!line._consume_at_explicit)line.consume_at=line.category==='packaging'?'final_good':'assembly_start';paint();return;}
    if(target?.closest?.('[data-cost-line]')&&target.name==='source_mode'){remember();const line=draft().lines.find(r=>r.id===target.closest('[data-cost-line]').dataset.costLine);if(line&&line.source_mode==='buy')line.gross_material_g_per_input_piece='';paint();}
  });
  return {init,load,view,afterRender,stop,action,scenarioPayload,quotePayload,routePayload};
})();
